  function init(){
    if(!root)return;
    document.addEventListener?.('visibilitychange',syncBanner);
    window.addEventListener?.('pagehide',()=>{if(bannerTimer!==null){clearTimeout(bannerTimer);bannerTimer=null}});
    window.addEventListener?.('pageshow',syncBanner);
