#board .board-queen-candidate.board-queen-choice{border:2px solid #b78b27;border-top-width:3px;box-shadow:0 0 0 1px #d9b54d55,inset 0 0 24px #d9b54d12}
#board .board-queen-card-head{display:grid;grid-template-columns:40px minmax(0,1fr) auto;gap:8px;align-items:center}
#board .board-queen-card-name{display:flex;flex-direction:column;gap:2px;min-width:0;overflow-wrap:anywhere}
#board .board-queen-card-name small{font-size:11px;color:var(--text-secondary)}
#board .board-queen-card-name strong{font-size:14px;line-height:1.4}
#board .board-queen-votes{font-size:21px;font-variant-numeric:tabular-nums;white-space:nowrap}
#board .board-queen-votes small{font-size:10px;margin-left:2px}
#board .board-queen-track{display:block;height:7px;overflow:hidden;border-radius:99px;background:color-mix(in srgb,var(--text-primary) 12%,var(--surface-raised))}
#board .board-queen-bar{display:block;height:100%;width:var(--queen-value);border-radius:inherit;background:var(--queen-color);transition:width 650ms cubic-bezier(.2,.7,.25,1)}
#board [data-queen-rank="1"] .board-queen-bar{background:linear-gradient(90deg,#ad7818,#f2cf68,#c38e26)}
@starting-style{#board .board-queen-bar{width:var(--queen-from,0%)}}
#board .board-queen-gold{display:inline-block;border:1px solid #8b6500;border-radius:999px;padding:2px 7px;background:#ffdf80;color:#3b2900;font-size:12px}
#board .board-queen-candidate .board-queen-gold{align-self:flex-start;font-size:10px;max-width:100%;box-sizing:border-box;overflow-wrap:anywhere}
#board .board-queen-chairman,#board .board-queen-tiebreak{overflow-wrap:anywhere}
#board .board-queen-rivalry{margin-top:16px;border-top:1px solid var(--border-subtle)}
@keyframes queen-speech-pop{from{opacity:0;transform:translateX(-6px) scale(.92)}to{opacity:1;transform:translateX(0) scale(1)}}
@keyframes queen-live-pulse{0%,100%{opacity:1}50%{opacity:.35}}
@media(max-width:1000px){#board .board-queen-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){#board .board-queen-reaction>span{min-width:0}#board [data-board-banner-dots]{overflow-x:auto;justify-content:flex-start}}
@media(max-width:480px){#board .board-queen-candidate{padding:10px;gap:8px}#board .board-queen-card-head{grid-template-columns:32px minmax(0,1fr) auto;gap:6px}#board .board-queen-card-head .board-avatar-frame,#board .board-queen-card-head .board-avatar{width:32px;height:32px;flex-basis:32px}#board .board-queen-card-name strong{font-size:13px}#board .board-queen-votes{font-size:18px}#board .board-queen-podium{padding:14px 10px 0}#board .board-queen-podium ol{gap:6px}}
@media(prefers-reduced-motion:reduce){#board .board-queen-speech,#board .board-queen-live i{animation:none}#board .board-queen-candidate,#board .board-queen-bar{transition:none}#board button.board-queen-candidate:hover:not(:disabled){transform:none}}
